use solana_rsa_verifier::{
    Error, verify_pkcs1_sha256, verify_pkcs1_sha384, verify_pkcs1_sha512, verify_pss,
};

// Generated by a deterministic Python signer, seed 20261125.
// Message bytes are b"solana-rsa-verifier". Public exponent is 3.
const MODULUS_2048: &str = "";
const N2048_SHA256_DIGEST: &str =
    "c690b0c615b5af8fedfb05d872b840f1b20ea63a6a6f32186d55e3c6621cba24";
const N2048_SHA256_SIGNATURE: &str = "";
const N2048_SHA384_DIGEST: &str = "300484ec9a2145bef8f3c9f027f331e540159561f105c1a4e75361e3248f448b2b9b5b5f0fe5efe5ba0c64ce90614012";
const N2048_SHA384_SIGNATURE: &str = "";
const N2048_SHA512_DIGEST: &str = "c0456bf85b966c09606a46cb544127e1c9c606bdc6a72f21a5873befa78e59efaf9f24ee8798508f275d7a296ed96a32f65c435426982628ab5376c36e18254c";
const N2048_SHA512_SIGNATURE: &str = "";
const PSS_2048_DIGEST: &str = "c690b0c615b5af8fedfb05d872b840f1b20ea63a6a6f32186d55e3c6621cba24";
const PSS_2048_SIGNATURE: &str = "";
const PKCS1_2048_SHORT_FF_SIGNATURE: &str = "";
const PSS_2048_ZERO_SALT_SIGNATURE: &str = "";
const MODULUS_3072: &str = "";
const N3072_SHA256_DIGEST: &str =
    "c690b0c615b5af8fedfb05d872b840f1b20ea63a6a6f32186d55e3c6621cba24";
const N3072_SHA256_SIGNATURE: &str = "";
const N3072_SHA384_DIGEST: &str = "300484ec9a2145bef8f3c9f027f331e540159561f105c1a4e75361e3248f448b2b9b5b5f0fe5efe5ba0c64ce90614012";
const N3072_SHA384_SIGNATURE: &str = "";
const N3072_SHA512_DIGEST: &str = "c0456bf85b966c09606a46cb544127e1c9c606bdc6a72f21a5873befa78e59efaf9f24ee8798508f275d7a296ed96a32f65c435426982628ab5376c36e18254c";
const N3072_SHA512_SIGNATURE: &str = "";
const PSS_3072_DIGEST: &str = "c690b0c615b5af8fedfb05d872b840f1b20ea63a6a6f32186d55e3c6621cba24";
const PSS_3072_SIGNATURE: &str = "";
const MODULUS_4096: &str = "";
const N4096_SHA256_DIGEST: &str =
    "c690b0c615b5af8fedfb05d872b840f1b20ea63a6a6f32186d55e3c6621cba24";
const N4096_SHA256_SIGNATURE: &str = "";
const N4096_SHA384_DIGEST: &str = "300484ec9a2145bef8f3c9f027f331e540159561f105c1a4e75361e3248f448b2b9b5b5f0fe5efe5ba0c64ce90614012";
const N4096_SHA384_SIGNATURE: &str = "";
const N4096_SHA512_DIGEST: &str = "c0456bf85b966c09606a46cb544127e1c9c606bdc6a72f21a5873befa78e59efaf9f24ee8798508f275d7a296ed96a32f65c435426982628ab5376c36e18254c";
const N4096_SHA512_SIGNATURE: &str = "";
