const PSS_4096_SIGNATURE: &str = "";

#[test]
fn pkcs1_accepts_sha256_sha384_and_sha512() {
    accept_pkcs1(
        MODULUS_2048,
        N2048_SHA256_DIGEST,
        N2048_SHA256_SIGNATURE,
        verify_pkcs1_sha256,
    );
    accept_pkcs1(
        MODULUS_2048,
        N2048_SHA384_DIGEST,
        N2048_SHA384_SIGNATURE,
        verify_pkcs1_sha384,
    );
    accept_pkcs1(
        MODULUS_2048,
        N2048_SHA512_DIGEST,
        N2048_SHA512_SIGNATURE,
        verify_pkcs1_sha512,
    );
    accept_pkcs1(
        MODULUS_3072,
        N3072_SHA256_DIGEST,
        N3072_SHA256_SIGNATURE,
        verify_pkcs1_sha256,
    );
    accept_pkcs1(
        MODULUS_3072,
        N3072_SHA384_DIGEST,
        N3072_SHA384_SIGNATURE,
        verify_pkcs1_sha384,
    );
    accept_pkcs1(
        MODULUS_3072,
        N3072_SHA512_DIGEST,
        N3072_SHA512_SIGNATURE,
        verify_pkcs1_sha512,
    );
    accept_pkcs1(
        MODULUS_4096,
        N4096_SHA256_DIGEST,
        N4096_SHA256_SIGNATURE,
        verify_pkcs1_sha256,
    );
    accept_pkcs1(
        MODULUS_4096,
        N4096_SHA384_DIGEST,
        N4096_SHA384_SIGNATURE,
        verify_pkcs1_sha384,
    );
    accept_pkcs1(
        MODULUS_4096,
        N4096_SHA512_DIGEST,
        N4096_SHA512_SIGNATURE,
        verify_pkcs1_sha512,
    );
}

#[test]
fn pss_accepts_a_32_byte_salt() {
    accept_pss(MODULUS_2048, PSS_2048_DIGEST, PSS_2048_SIGNATURE);
    accept_pss(MODULUS_3072, PSS_3072_DIGEST, PSS_3072_SIGNATURE);
    accept_pss(MODULUS_4096, PSS_4096_DIGEST, PSS_4096_SIGNATURE);
}

#[test]
fn a_pkcs1_signature_is_not_a_pss_signature() {
    let modulus = hex(MODULUS_2048);
    let signature = hex(N2048_SHA256_SIGNATURE);
    let digest = hex32(N2048_SHA256_DIGEST);
    assert_eq!(
        verify_pss(&modulus, &signature, &digest),
        Err(Error::Padding)
    );
}

#[test]
fn a_pss_signature_is_not_a_pkcs1_signature() {
    let modulus = hex(MODULUS_2048);
    let signature = hex(PSS_2048_SIGNATURE);
    let digest = hex32(PSS_2048_DIGEST);
    assert_eq!(
        verify_pkcs1_sha256(&modulus, &signature, &digest),
        Err(Error::Padding)
    );
}

#[test]
fn a_short_ff_run_is_rejected() {
    let modulus = hex(MODULUS_2048);
    let signature = hex(PKCS1_2048_SHORT_FF_SIGNATURE);
    let digest = hex32(N2048_SHA256_DIGEST);
    assert_eq!(
        verify_pkcs1_sha256(&modulus, &signature, &digest),
        Err(Error::Padding)
    );
}

#[test]
fn a_zero_length_salt_is_rejected() {
    let modulus = hex(MODULUS_2048);
    let signature = hex(PSS_2048_ZERO_SALT_SIGNATURE);
    let digest = hex32(PSS_2048_DIGEST);
    assert_eq!(
        verify_pss(&modulus, &signature, &digest),
        Err(Error::Padding)
    );
}

#[test]
fn rejects_a_modulus_that_does_not_fill_its_width() {
    let mut modulus = hex(MODULUS_2048);
    modulus[0] &= !0x80;
    let signature = hex(N2048_SHA256_SIGNATURE);
    let digest = hex32(N2048_SHA256_DIGEST);
    assert_eq!(
        verify_pkcs1_sha256(&modulus, &signature, &digest),
        Err(Error::Modulus)
    );
}

#[test]
fn rejects_a_modulus_of_an_unsupported_length() {
    let digest = hex32(N2048_SHA256_DIGEST);
    assert_eq!(
        verify_pkcs1_sha256(&[0x80, 0x01], &[0x00, 0x01], &digest),
        Err(Error::Modulus)
    );
}

#[test]
fn rejects_a_signature_of_a_different_length() {
    let modulus = hex(MODULUS_2048);
    let digest = hex32(N2048_SHA256_DIGEST);
    assert_eq!(
        verify_pkcs1_sha256(&modulus, &[0x01], &digest),
        Err(Error::Representative)
    );
}

fn accept_pkcs1<const N: usize>(
    modulus: &str,
    digest: &str,
    signature: &str,
    verify: fn(&[u8], &[u8], &[u8; N]) -> Result<(), Error>,
) {
    let modulus = hex(modulus);
    let signature = hex(signature);
    let mut digest_bytes = [0u8; N];
    decode(digest, &mut digest_bytes);
    assert_eq!(verify(&modulus, &signature, &digest_bytes), Ok(()));
    signature_bytes_tamper(&modulus, &signature, &digest_bytes, verify);
}

fn accept_pss(modulus: &str, digest: &str, signature: &str) {
    let modulus = hex(modulus);
    let signature = hex(signature);
    let digest = hex32(digest);
    assert_eq!(verify_pss(&modulus, &signature, &digest), Ok(()));
}

fn signature_bytes_tamper<const N: usize>(
    modulus: &[u8],
    signature: &[u8],
    digest: &[u8; N],
    verify: fn(&[u8], &[u8], &[u8; N]) -> Result<(), Error>,
) {
    let mut tampered = signature.to_vec();
    let last = tampered.len() - 1;
    tampered[last] ^= 1;
    assert!(verify(modulus, &tampered, digest).is_err());
}

fn hex(text: &str) -> Vec<u8> {
    let mut out = vec![0u8; text.len() / 2];
    decode(text, &mut out);
    out
}

fn hex32(text: &str) -> [u8; 32] {
    let mut out = [0u8; 32];
    decode(text, &mut out);
    out
}

fn decode(text: &str, out: &mut [u8]) {
    assert_eq!(text.len(), out.len() * 2);
    for i in 0..out.len() {
        out[i] = u8::from_str_radix(&text[i * 2..i * 2 + 2], 16).unwrap();
    }
}
